// sivananda_ta.dart
// ஸ்வாமி சிவானந்தா மேற்கோள்கள் மற்றும் கட்டுரைகள்

import '../articlesquotes.dart';


final sivanandaSaintTa =   Saint(
  'sivananda',
  'சுவாமி சிவானந்தர்',
  'assets/images/sivananda.jpg',
  [
    'ஒரு சிறு அளவு நடைமுறை, ஒரு பெரும் அளவு கோட்பாட்டை விட மதிப்புடையது!',
    'சிறிய செயல்களில்கூட உன் இதயம், மனம், ஆன்மாவை முழுமையாக இணை; அதுவே வெற்றியின் ரகசியம்.',
    'உள்ளத்தில் அமைதியை காணவில்லை என்றால், வேறு எங்கும் அதை காண முடியாது.',
    'உள்ளொளியை தாங்கினால், இருளை அஞ்ச வேண்டாம்.',
    'இன்பமும் துன்பமும் மனத்தின் படைப்புகள்; மனக் கட்டுப்பாடே உயர்ந்த யோகம்.',
    'காமம், வெறுப்பு, பேராசை, சுயநலம், பொறாமை என்ற களைகளை அகற்றி, முதலில் இதயத் தோட்டத்தில் அமைதியை வளர்த்து கொள்ளு.',
    'உள்ளம் நோக்கு; உன்னுள் மறைந்திருப்பது இறைவன், உன்னுள் நிலைத்திருப்பது அமர ஆன்மா.',
    'அன்பு பலனை எதிர்பார்க்காது; அன்பு அச்சத்தை அறியாது; தெய்வீக அன்பு கொடுக்கும், கேட்காது.',
    'பொறுமையும் தொடர்ந்து செய்யும் சாதனையும் ஆன்மீக உணர்வின் முழு ரகசியம்; அவசரம் வேண்டாம்.',
    'நீ மகிழ விரும்புவது போல, பிறரையும் உண்மையாக மகிழ்விக்க முயல்; உதவும் சொல் பேசு, உற்சாக புன்னகை தா, கருணை செயல் செய்.',
    'சேவை செய், அன்பு செய், கொடு, தூய்மை அடை, தியானி, உணர்ந்திடு.',
    'ஒரு சிறு நடைமுறை, ஒரு பெரும் கோட்பாட்டை விட மேல்.',
    'ஆன்மீகப் பாதை கூர்மையான கத்தி நுனி போன்றது.',
    'இறைவன் தொலைவில் இல்லை; உன்னுள் குடியிருக்கும் உண்மை, உலகில் எதையும் விட உனக்கு நெருக்கமானது.',
    'அன்பே உலகின் மிகப் பெரிய படைப்பாற்றல் சக்தி.',
    'இந்த உலகமே உன் சிறந்த ஆசிரியன்; ஒவ்வொரு அனுபவமும் ஒரு பாடம்; கற்று ஞானி ஆகு.',
    'சுய பகுப்பாய்வு முன்னேற்றத்தின் உயர்ந்த கலை.',
    'சுயநலம் இல்லாத இடத்தில் அமைதி, ஆனந்தம், ஒளி விளங்கும்.',
    'உன் விதியின் எழுத்தாளர் நீயே; இதை உருவாக்கியது நீயே; முழுப் பொறுப்பும் உன்னதே.',
    'சரியான ஆரோக்கியம், மகிழ்ச்சி, வெற்றி ஆகியவற்றின் ரகசியம் மனக் கட்டுப்பாடு.',
    'ஞானம் பெற்று, வாழ்க்கையின் உண்மையான குறிக்கோளை உணர்.',
    'சுய ஒழுக்கத்தின் விதையை விதை; அன்பால் அதை நீர் ஊற்று.',
    'ஆன்மீக வாழ்க்கையின் கிரீடம் ஒற்றுமை உணர்வு.',
    'எப்போதும் நேர்மறை, கட்டுமான சிந்தனைகளை வளர்த்து கொள்.',
    'நிலையானதை அடைய விரும்பினால், நிலையற்றதை விடு.',
    'ஒவ்வொரு தோல்வியும் வெற்றிக்கான படிக்கல்.',
    'தன்னிடம் நேர்மையாக இருப்பவருக்கு, உண்மையில் நல்லவராக இருப்பதே மிகக் கடினம்.',
    'தாழ்மை கோழைத்தனம் அல்ல; மென்மை பலவீனம் அல்ல; அவை ஆன்மீக சக்திகள்.',
    'உன்னுள் இருக்கும் தெய்வீக சக்தி, வெளியுள்ள எதையும் விட வலிமையானது.',
    'உண்மையான ஆன்மீகம், வாழ்க்கைப் போட்டியில் வீரராக இருப்பது.',
    'எப்படி சிந்திக்கிறாயோ, அப்படியே ஆகிறாய்.',
    'மனிதன் சிந்தனையை விதைக்கிறான்; செயலை அறுவடை செய்கிறான்; செயலை விதைக்கிறான்; பழக்கத்தை அறுவடை செய்கிறான்; பழக்கத்தை விதைக்கிறான்; குணநலனை அறுவடை செய்கிறான்; குணநலனை விதைக்கிறான்; விதியை அறுவடை செய்கிறான்.',
    'மலை சிறு மண்துகள்களால் ஆனது; கடல் சிறு நீர்த்துளிகளால் ஆனது; வாழ்க்கையும் சிறு செயல்கள், சொற்கள், சிந்தனைகளின் தொடர்ச்சி.',
    'தீமையை காணும் பழக்கத்தை அழித்து, நன்மையை காணும் பண்பை வளர்த்து கொள்.',
    'இருமை உள்ள இடத்தில் பயம் உள்ளது; பயம் மனமே; சுய உணர்வில் பயமில்லை.',
    'அனைத்து துன்பங்களுக்கும் காரணம் மனமே.',
    'பயனற்ற தகவல்களை மூளையில் சேமிக்காதே; மனத்தை மனமற்றதாக்க கற்று கொள்.',
    'அழிவை நினைத்தால் அது உன்னை நாடும்; மரணத்தை நினைத்து மனம் தங்கினால் அதனை வேகப்படுத்தும்; நம்பிக்கையுடன் நல்ல சிந்தனை கொண்டால் வாழ்க்கை பாதுகாப்பாகும்.',
    'ஒவ்வொரு சிந்தனையும் முகத்தில் ஓர் அடையாளம் பதிக்கும்.',
    'இன்பம் துன்பம் மனத்தின் படைப்புகள்.',
    'தூய அமைதியான மனமே ஞானத்திற்கு அவசியம்.',
    'ஒருமுகப்படுத்தும் திறன் எல்லோருக்கும் உள்ளதே; அது அதிசயம் அல்ல.',
    'மனக் கட்டுப்பாடே உயர்ந்த யோகம்.',
    'சிந்தனை செயலில் மாறும்; செயல் பழக்கமாகும்; பழக்கம் குணமாகும்; குணம் விதியாகும்.',
    'மனம் கட்டுப்படுத்தப்பட வேண்டிய காட்டு குதிரை போன்றது.',
    'தனிப்பட்ட ஆன்மாவின் பார்வையை கட்டுப்படுத்துவது மனமே.',
    'வலிமையான சிந்தனைகள் நிஜத்தை உருவாக்கும்.',
    'நீ அதிகம் தியானிக்கிறபோது, நீ உடல் அல்ல, அமர ஆன்மா என்பதை உணர்வாய்.',
    'முகம் மனத்தின் கண்ணாடி.',
    'மனம் ஞானத்தின் பெரிய களஞ்சியம்; சிந்தனைகள் அதன் வாயில்.',
    'தியானம் சிந்தனைகள் கரைந்து, தூய சித்தத்தில் நிலை பெறும் நிலை.',
    'தொடர்ந்த தியானம் உள்ளுணர்வு ஞானத்தின் கதவுகளைத் திறக்கும்.',
    'மௌனம் இறைவனின் மொழி; மௌனம் இதயத்தின் மொழி.',
    'தியானம் தொடக்கத்தில் கடினம்; முடிவில் அமர ஆனந்தம் தரும்.',
    'நிலையான மகிழ்ச்சி பெற மனத்தை அமைதிப்படுத்தி, அதை மீறிச் செல்ல வேண்டும்.',
    'தொடர்ந்து தியானி; தியானம் நிலையான ஆனந்தத்துக்கு வழி.',
    'உள்ள்நோக்கு; சுய ஆய்வு செய்; உணர்ந்து அறி.',
    'வெளிப்புற முரண்பாடுகளை நீக்க, உள்ளார்ந்த அமைதியை நாடு.',
    'மனதை வெளியில் அலைவதைத் தடுத்து, அமைதியாகக் கவனி.',
    'மௌனம் தெய்வீகத்துக்கான வாசல்.',
    'சிந்தனை இல்லாத விழிப்பு நிலை ஒவ்வொரு தருணமும் சமாதி நிலை.',
    'மௌனத்தில் ஆழ்ந்தால், உள்ள குரலை கேட்பாய்.',
    'தியானத்தின் உண்மை அர்த்தம் தெய்வத்துடன் ஒன்றாக இருப்பது.',
    'தியானம் மூலம் உண்மையான சுயத்தை கண்டறியலாம்.',
    'தியானமே நிலையான அமைதிக்கான வழி.',
    'ஒவ்வொரு மனிதனும் தன் ஆரோக்கியம் அல்லது நோயின் படைப்பாளர்.',
    'மகிழ்ச்சியுடன் குதித்து, பாடி, சிரித்து வாழும் நிலையே ஆரோக்கியம்.',
    'சிறந்த உடலில் சிறந்த மனம்.',
    'வலி விழிப்பூட்டும் சிறந்த ஆசான்; மறைந்துள்ள திறன்களை எழுப்பும்.',
    'உடல் நலன் என்பது இயற்கை ஒழுங்கை பின்பற்றி உடல் சரியாக செயல்படுதல்.',
    'ஒன்றுபட்ட உணர்வு அதிகரிக்கையில் ஆரோக்கியமும் உயரும்.',
    'நம்பிக்கை, அமைதி, மகிழ்ச்சி இல்லாத உடலில் இசைவு குலையும்; அவர்கள் துன்பப்படுவர்.',
    'உன் முகம் கண்ணாடி; உன் சிந்தனை அதில் பிரதிபலிக்கும்.',
    'தீய சிந்தனை முகத்தையும் ஒளிவட்டத்தையும் இருண்டாக்கும்; தெய்வீக சிந்தனை பிரகாசமாக்கும்.',
    'இதயத் தோட்டத்தில் அமைதியை வளர்த்து கொள்.',
    'அன்பு கொடுப்பவரை அழகாக்கி, பெறுபவரை உயர்த்தும்.',
    'அன்பு பகிர்வதும் சேவை செய்வதும் ஆகும்.',
    'அன்பு பலன் எதிர்பார்க்காது; அச்சம் அறியாது; தெய்வீக அன்பு கொடுக்கும், கேட்காது.',
    'அன்பே ஒரே சட்டம்; அன்பே ஒரே உண்மை.',
    'அன்பே உலகின் மிகப் பெரிய படைப்பாற்றல் சக்தி.',
    'அன்பு இருக்கும் இடத்தில் இறைவன் இருக்கிறார்.',
    'வெறுப்பை வெறுப்பால் வெல்ல முடியாது; அன்பால் மட்டுமே வெல்ல முடியும்.',
    'ஒவ்வொருவரிடமும் கருணையுடன் இரு; ஒவ்வொருவரும் தமது போராட்டத்தில் இருக்கிறார்கள்.',
    'அனைவரையும் அன்பு செய், அனைவருக்கும் சேவை செய்; எல்லோரும் இறைவனில் ஒன்றே.',
    'பிறருக்கு சேவை செய்வது இறைவனுக்கு சேவை செய்வது.',
    'சிறிய செயல்களிலும் முழு உள்ளத்தையும் இணை; அதுவே வெற்றியின் ரகசியம்.',
    'அழிவை உண்டாக்கும் சக்திக்காக அறிவியல் கதவின் முன் பிச்சைக்காரனாக நிற்காதே.',
    'போராட்டம் கடினமானால், வெற்றி மகத்தானது.',
    'பிறர் சொல்வதை கவலைப்படாதே; நியாயமானதை செய்; தெளிந்த மனச்சாட்சியுடன் மகிழ்ச்சியாக இரு.',
    'இன்று உன்னுடையது; நாளை வராமலும் போகலாம்.',
    'நல்ல உடல் நலம் இல்லாத வாழ்க்கை துன்பமானது.',
    'மகிழ்ச்சியுடன் இரு; உன் இலட்சியத்தை பிடித்து கொள்; அனைவருக்கும் பணியாளர் ஆகு.',
    'கர்ம விதி தண்டனை அல்ல; காரண-விளைவு சட்டம்.',
    'வாழ்க்கையின் உண்மையான இலக்கு நாம் வந்த மூலத்திற்குத் திரும்புவது.',
    'ஆன்மீக வாழ்க்கைக்கு மிகப்பெரிய துணை தியானம்; அடுத்தது நல்ல நட்பு.',
    'பிறருக்காக நன்மை செய்யும் அளவிற்கு இதயம் தூய்மையடையும்.',
    'உன் விதியின் எஜமானன் நீயே.',
    'இந்த பிரபஞ்சம் அவனது இருப்பின் விசால ஆலயம்.',
    'ஒவ்வொரு ஆன்மாவும் தெய்வீகத் திறன் கொண்டது.',
    'அனைத்து ஞானமும் நம்முள் உள்ளது; அதை வெளிப்படுத்துவது மனித மனம்.',
    'உயர்வு நிலைகளில் இறைவன் பல வழிகளில் வெளிப்படுகிறார்.',
    'இந்த உலகம் இறைவனின் ஆனந்தத்தின் பெருக்கு.',
    'வாழ்க்கையின் உண்மை அர்த்தம், நீ இறைவனுடன் ஒன்றென உணர்வது.',
    'நீ தெய்வீகத்தின் தீப்பொறி; இதை உணர்ந்து அச்சமின்றி வாழ்.',
    'கண்ணுக்குப் புலப்படாத சித்தமே அனைத்தையும் ஒளிரச் செய்கிறது.',
    'இறைவனை அதிகம் நேசிக்கிறபோது, அனைவரையும் நேசிக்க இயலும்; ஏனெனில் அவர்களில் இறைவனை காண்பாய்.',
    'வெளி, உள் இயற்கையை கட்டுப்படுத்தி தெய்வீகத்தை வெளிப்படுத்துவதே வாழ்க்கையின் இலக்கு.',
    'உயர்வதற்கான வழி, நமக்கு அருகிலுள்ள கடமையைச் செய்வது.',
    'எல்லாம் இறைவன்; எல்லாம் ஆன்மா; எல்லாம் ஒன்றே.',
    'மனித வாழ்க்கையின் குறிக்கோள் சுதந்திரத்தை அடைவது.',
    'சேவை செய், அன்பு செய், கொடு, தூய்மை அடை, தியானி, உணர்ந்திடு—இது அனைத்து சாஸ்திரங்களின் சாரம்.',
    'சிறந்த சூழ்நிலை காத்திருக்காதே; வாழ்க்கை தடைகளற்றதல்ல; இப்போது தொடங்கு.',
    'சுயநலமற்ற சேவை உயர்ந்த வழிபாடு; தூய இதயத்துடன் மனிதகுலத்தை சேவித்தால் உயிரோடு இருக்கும் இறைவனை வணங்குகிறாய்.',
    'ஆன்மீகம் உலகத்தை விட்டு ஓடுவது அல்ல; சுயநலம், அகந்தை, பற்றுகளை விடுவது.',
    'மனித வாழ்க்கையின் குறிக்கோள் இறை உணர்வு; ஒவ்வொரு சிந்தனை, சொல், செயலும் அதற்கே வழி காட்ட வேண்டும்.',
    'தியானம் சுய உணர்விற்கான அரச பாதை; தியானமின்றி மனம் தூய்மையடையாது; தூய்மை இல்லாமல் அமைதி இல்லை.',
    'மனக் கட்டுப்பாடு கடினமான பணி; ஆனால் மனிதன் அடையக்கூடிய மகத்தான வெற்றி.',
    'உண்மையான துறவு செயலை மறுப்பது அல்ல; பலன் ஆசையை விடுவது.',
    'ஒழுக்கமற்ற மனம் அலைகிறது; தொடர்ந்த சாதனை, விருப்பமின்மை மூலம் அது கட்டுப்படும்.',
    'ஒவ்வொரு முகத்திலும் இறைவனை காண்; ஒவ்வொரு இதயத்திலும் அவன் இருப்பை உணர்; வாழ்க்கை முழுவதும் வழிபாடாகும்.',
    'ஆன்மீக வளர்ச்சி மர வளர்ச்சி போல மெதுவானது; பொறுமை மற்றும் தொடர்ச்சி முக்கியம்.',
    'பிரார்த்தனை வார்த்தை உச்சரிப்பு அல்ல; தெய்வத்துடன் இணைவதற்கான ஆன்மாவின் ஆழ்மனக் குரல்.',
    'நேரமில்லை என்று குறை கூறாதே; வீண் பேச்சிற்கு நேரம் இருந்தால் தியானத்திற்கும் இருக்கும்.',
    'மனம் எதை தொடர்ந்து சிந்திக்கிறதோ அதே வடிவம் எடுக்கும்; இறைவனை சிந்தித்தால் மனம் தெய்வீகமாகும்.',
    'மௌனம் ஆன்மீக ஆசிரியன்; அதில் மனம் அமைதியடைந்து ஆன்மக் குரல் கேட்கும்.',
    'உண்மையான மகிழ்ச்சி வெளிப்பொருள்களிலிருந்து வராது; உள்ள அமைதியிலிருந்து பிறக்கும்.',
    'சுய ஒழுக்கமே ஆன்மீக வாழ்க்கையின் அடித்தளம்.',
    'குரு மனிதர் மட்டுமல்ல; அறியாமை இருளை அகற்றும் தெய்வீக ஒளி.',
    'எளிய வாழ்க்கை வாழ்; ஆசைகளை கட்டுப்படுத்து; உயர்ந்த சிந்தனைகளை வளர்த்து கொள்—நிலையான அமைதியின் ரகசியம்.',
    'உடல் ஒரு கருவி; அதை தர்ம செயல்களுக்கும் ஆன்மீக சாதனைக்கும் பயன்படுத்து.',
    'இறைவன் மீது நம்பிக்கையும், தன்னம்பிக்கையும் இணைந்து இருக்க வேண்டும்.',
    'தொடர்ச்சி மிக முக்கியம்; தினமும் சிறிது செய்வது அவ்வப்போது அதிகம் செய்வதை விட மேல்.',
    'பிறரிடம் பூரணத்தை தேடாதே; உன்னுள் சுய ஆய்வு மூலம் தேடு.',
    'ஒவ்வொரு சிரமமும் ஆன்மீக வளர்ச்சிக்கான தெய்வப் பாடம்.',
    'பற்றின்மை அலட்சியம் அல்ல; சமநிலை மனதுடன் கடமை செய்வது.',
    'உலகிற்கு செய்யும் மிகப் பெரிய சேவை, உன் இதயத்தை தூய்மைப்படுத்துவது.',
    'அகந்தை அழிந்தால், அன்பு இயல்பாகப் பெருகும்.',
    'தூய இதயமே இறைவனின் உண்மையான ஆலயம்.',
    'நெறியுள்ள வாழ்வு ஆன்மீக வாழ்க்கையின் தொடக்கம்.',
    'இந்திரியங்கள் வலிமையானவை; மனம் அதைவிட வலிமையானது; புத்தி அதைவிட உயர்ந்தது; ஆன்மா பரமமானது.',
    'திருப்தியே பெரிய செல்வம்; மன அமைதியே உயர்ந்த மகிழ்ச்சி.',
    'ஆன்மீக முன்னேற்றத்தை அதிசயங்கள் மூலம் அல்ல; அகந்தை, ஆசைகள் குறைவதால் அளவிடு.',
    'யோகப் பாதை சமநிலையின் பாதை—பணி, ஓய்வு; பக்தி, ஞானம்; முயற்சி, சரணாகதி.',
    'ஒழுக்கமான வாழ்க்கை அடக்குமுறை அல்ல; புத்திசாலித்தனமான கட்டுப்பாடு.',
    'அன்புள்ள இடத்தில் பயமில்லை; பயமுள்ள இடத்தில் அன்பு உதயிக்கவில்லை.',
    'எதிர்பார்ப்பின்றி சேவை செய்; நிபந்தனையின்றி அன்பு செய்; பற்றின்றி செயல் செய்.',
    'மனம் எதைப் பெறுகிறதோ அதுவாக மாறும்; உயர்ந்த சிந்தனைகளால் அதை ஊட்டு.',
    'ஆன்மீக அறியாமையே அனைத்து துன்பங்களின் வேர்.',
    'கருணையுடன், இரக்கத்துடன், மன்னிப்புடன் இரு—இவை ஆன்மீக தேடுபவரின் ஆபரணங்கள்.',
    'செல்வத்தை விட அகந்தையைத் துறப்பதே உயர்ந்த துறவு.',
    'சிரமங்களின் நடுவே அமைதியாக இருப்பதே ஆன்மீக வாழ்க்கையின் சோதனை.',
    'விமர்சனத்தில் சக்தியை வீணாக்காதே; சுய முன்னேற்றத்திற்கு பயன்படுத்து.',
    'இறைவன் தொலைவில் இல்லை; உன் மூச்சை விட நெருக்கம்.',
    'அமைதியான மனமே மிகப் பெரிய ஆசீர்வாதம்.',
    'சிந்தனை, சொல், செயலில் உண்மையை கடைப்பிடித்தால் முழு உள்ளம் தூய்மையடையும்.',
    'ஞான ஒளி அறியாமை இருளை சூரியன் போல் அகற்றும்.',
    'ஆசைகள் மறைந்தால் அமைதி உதிக்கும்.',
    'ஆன்மீக வாழ்க்கை வாழ்க்கையிலிருந்து தப்பிப்பு அல்ல; அதன் ஆழமான புரிதல்.',
    'தூய்மை, பொறுமை, தொடர்ந்து முயற்சி—யோக வெற்றியின் மூன்று தூண்கள்.',
    'சிறிதளவு ஆன்மீக சாதனையும் பெரிய பயத்திலிருந்து காப்பாற்றும்.',
    'வாழ்க்கையின் இலக்கு அனைத்துடனும் ஒன்றென உணர்வது.',
    'நீ அதிகம் கொடுத்தால் அதிகம் பெறுவாய்—இது தெய்வீக வளத்தின் சட்டம்.',
    'பிரார்த்தனை, தியானம் உள்ளத்தை மாற்றி உலகிற்கு அமைதியை பரப்பும்.',
    'தாழ்மையே உண்மையான ஞானத்தின் அடையாளம்.',
    'ஆசை அமைதியின்மையின் வேர்; துறவு அமைதியின் வேர்.',
    'ஆன்மீக தேடுபவன் மகிழ்ச்சியுடன், பொறுமையுடன், நம்பிக்கையுடன் இருக்க வேண்டும்.',
    'ஒவ்வொரு தருணமும் ஆன்மீக வளர்ச்சிக்கான வாய்ப்பு.',
    'இதயம் தூய்மையாகவும் நேர்மையாகவும் இருந்தால் தெய்வ அருள் இறங்கும்.',
    'தொடர்ந்த முயற்சி, அசைக்க முடியாத நம்பிக்கை—வெற்றியின் ரகசியம்.',
    'தன்னை வெல்வது உலகை வெல்வதை விட உயர்ந்தது.',
    'உலகில் வாழ்; ஆனால் உலகம் உன்னுள் வாழ விடாதே.',
    'ஆன்மீக சாதனை மறைமனதை தூய்மைப்படுத்தி குணநலனை மாற்றும்.',
    'புனிதரிலும் பாவியிலும் ஒரே சுயத்தை காண்.',
    'அன்பு இதயத்தை விரிவாக்கி பிரிவு உணர்வை அழிக்கும்.',
    'ஒழுக்கமான மனம் மகிழ்ச்சிக்கு வழி; ஒழுக்கமற்ற மனம் துன்பத்திற்கு வழி.',
    'கடமையை மகிழ்ச்சியுடன் இறைவனுக்கான அர்ப்பணிப்பாக செய்.',
    'ஆன்மா எப்போதும் சுதந்திரம், தூய்மை, ஆனந்தம் உடையது.',
    'ஆன்மீகம் தினசரி வாழ்க்கையில் வாழப்படும் செயல்முறை மதம்.',
    'பொறுமை, சகிப்பு—உள் வலிமையின் அடையாளங்கள்.',
    'கட்டுப்பாடற்ற மனமே மிகப் பெரிய எதிரி.',
    'எளிய வாழ்க்கை மன தெளிவை தரும்.',
    'இறை உணர்வே மனித முயற்சிகளின் உச்சம்.',
    'உன் வாழ்க்கை அமைதி, நல்லெண்ணத்தின் செய்தியாக இருக்கட்டும்.',
    'கருணை சாதனை இதயத்தை தூய்மைப்படுத்தும்.',
    'பக்தி இல்லாத ஞானம் வறண்டு போகும்; ஞானம் இல்லாத பக்தி குருடு.',
    'ஆன்மீக வாழ்க்கை எப்போதும் விழிப்புணர்வை தேடுகிறது.',
    'அமைதி உள்ளத்திலிருந்து வருகிறது; வெளியே தேடாதே.',
    'உயர்ந்த சிந்தனை அமைதியான பிரார்த்தனை.',
    'ஞானிகளுடன் உறவு மனத்தை தூய்மைப்படுத்தும்.',
    'யோகத்தின் நோக்கம் தெய்வத்துடன் ஒன்றாகுதல்.',
    'வெறுப்பு, கோபம், பொறாமையை விடு; அன்பும் மன்னிப்பும் வளர்த்து கொள்.',
    'ஆன்மீக முன்னேற்றம் உள்ள மாற்றத்தால் அளவிடப்படுகிறது.',
    'சுய கட்டுப்பாட்டை கற்பிப்பதே உயர்ந்த கல்வி.',
    'தாழ்மை உள்ள இடத்தில் தெய்வ அருள் ஓடும்.',
    'நற்குண வாழ்க்கை அமைதியின் அடித்தளம்.',
    'ஒவ்வொரு செயலையும் இறைவனுக்கு அர்ப்பணித்து யோகமாக மாற்று.',
    'சுய பகுப்பாய்வு சுய தூய்மைக்கு வழி.',
    'தூய அமைதியான மனத்தில் தெய்வம் வெளிப்படும்.',
    'ஆன்மீக வாழ்க்கை தொடர்ச்சியான மேம்பாட்டு பயணம்.',
    'பலன் பற்றை விடுத்து மகிழ்ச்சியுடன் செயல் செய்.',
    'மௌனத்தில் கேட்பவரை உள்ள குரல் வழிநடத்தும்.',
    'உண்மையே வெல்லும்; உண்மையே இறைவன்.',
    'வாக்கு கட்டுப்பாடு வலிமையான ஆன்மீக ஒழுக்கம்.',
    'இறைவனை நேசிக்கும் இதயம் அனைத்து உயிர்களையும் நேசிக்கும்.',
    'சிந்தனை, சொல், செயலில் ஒற்றுமை யோகமாகும்.',
    'நம்பிக்கை சந்தேக மலைகளை அகற்றும்.',
    'பொறுமை சாதனை கோபத்தை அழிக்கும்.',
    'தாழ்மையுடன், பக்தியுடன் சேவை செய்.',
    'ஆன்மீக விழிப்பு ஒவ்வொரு மனிதனின் பிறப்புரிமை.',
    'சுயத்தை உணர்ந்து என்றும் சுதந்திரமாக இரு.'
  ],
    [
      Article(
          heading: 'குருவின் பங்கு',
          body: 'அஜ்ஞானத் திமிரந்தஸ்ய ஞானாஞ்ஜன-சலகாயா;\n\nசக்ஷுருன்மிலிதம் யேன தஸ்மை ஸ்ரீகுரவே நமஃ.\n\nஅறியாமையின் இருளால் மூடப்பட்ட கண்களை, ஞானம் எனும் மைதண்டால் திறந்து விடும் அந்த குருவுக்கு வணக்கம் (குருகீதா).\n\nகுரு என்பவன் சாதகனை வழிநடத்த தனிப்பட்ட வடிவில் வெளிப்படும் கடவுளே. இறைஅருள் குருவின் வடிவம் எடுக்கிறது. குருவைக் காண்பதே கடவுளைக் காண்பது. குரு கடவுளோடு ஒன்றியவர். அவர் பிறருள் பக்தியை எழுப்புகிறார்; அவரது இருப்பே அனைத்தையும் தூய்மைப்படுத்துகிறது.\n\nகுரு தனி மனிதனுக்கும் அமரத்துவத்துக்கும் இடையே உள்ள உயிர்ப்பாலம். ‘இதிலிருந்து அதற்கு’ உயர்ந்தவர்; இரு உலகங்களுக்கும் தடையற்ற அணுகல் பெற்றவர். அமரத்துவத்தின் வாசலில் நின்று, போராடும் ஆன்மாவை ஒரு கையால் உயர்த்தி, மறுகையால் நித்திய ஆனந்தம், அளவற்ற சத்-சித் உலகிற்குக் கொண்டு செல்கிறார்.\n\nசத்குரு\n\nபுத்தகப் படிப்பால் மட்டும் ஒருவர் குருவாக மாற முடியாது. வேதங்களை அறிந்து, அனுபவ ஞானத்தால் ஆத்மாவை உணர்ந்தவரே குரு. ஜீவன்முக்தரே உண்மையான ஆன்மீக ஆசான்—அவரே சத்குரு. அவர் பரபிரம்மமே; பரமாத்மாவுடன் ஒன்றியவர்; பிரம்மஞானி.\n\nசித்திகளின் உடைமை குருவின் மகத்துவத்தின் அளவுகோல் அல்ல. சத்குருக்கள் பொதுவாக அதிசயங்களை வெளிப்படுத்தார்; சில நேரங்களில் சாதகர்களில் நம்பிக்கையை எழுப்பவே அவை தோன்றலாம். சத்குரு எண்ணற்ற சித்திகளால் நிறைந்தவர்; தெய்வீக ஐஸ்வர்யத்தின் முழுமை அவரிடமே.\n\nசத்குரு பிரம்மமே. ஆனந்தம், ஞானம், கருணை ஆகியவற்றின் பெருங்கடல். அவர் உன் ஆன்மாவின் நாவிகன். துன்பங்களை நீக்கி, சரியான தெய்வீகப் பாதையை காட்டி, அறியாமையின் மறையை அகற்றி, உன்னை அமரனாக்குகிறார். அவரை மனிதனாக மட்டுமே கருதாதே; அவ்வாறு கருதினால் அது மிருகப்பண்பு. குருவை வழிபட்டு பணிவுடன் வணங்கு.\n\nகுரு கடவுளே. அவரின் ஒரு சொல்—இறைச் சொல். அவர் போதிக்க வேண்டியதில்லை; அவரின் அருகாமையே உயர்வளிக்கிறது. அவரது சன்னிதானமே ஆத்ம ஒளி. அவருடன் வாழ்வதே ஆன்மீக கல்வி.\n\nமனிதன் மனிதனிடமிருந்தே கற்கிறான்; அதனால் கடவுள் மனித உடலால் போதிக்கிறார். உன் குருவில் முழுமையின் மனித மாதிரியைப் பார்க்கிறாய். அவ்வளவு உயர்ந்த ஆன்மாவை வழிபட மனம் தானே ஏற்கும்.\n\nகுரு—மோக்ஷத்தின் வாசல். ஆனால் அதில் நுழைய வேண்டியது சாதகனே. குரு துணை; சாதனை செயல் சாதகனிடமே.\n\nகுருவின் அவசியம்\n\nஆன்மீகப் பாதையின் தொடக்கத்தில் குரு அவசியம். எரியும் மெழுகுவர்த்தியாலே மற்றொன்று ஏற்றப்படும்; ஒளிபெற்ற ஆன்மாவே மற்றொன்றை ஒளியூட்ட முடியும்.\n\nதனித்து தியானம் செய்பவர்கள் பின்னர் தடைகள் வந்தபோது குருவின் தேவை உணர்கிறார்கள்; அப்பொழுது ஆசானைத் தேடுகின்றனர்.\n\nபத்ரிநாத் சென்றவரே பாதையைச் சொல்ல முடியும். ஆன்மீகப் பாதை இன்னும் நுணுக்கமானது; மனம் வழிதவறச் செய்யும். குரு குழிகளை நீக்கி சரியான வழி காட்டுவார்—‘இது மோக்ஷம்; அது பந்தம்’ என்று.\n\nசாஸ்திரங்கள் காடு போன்றவை—மறைபொருள், முரண்பாடு, உள்நுட்ப அர்த்தம் நிறைந்தவை. சரியான பொருளை விளக்க குரு தேவை.\n\nஒவ்வொரு சாதகனுக்கும் குரு அவசியம். தன் குறைகளைத் தானே காண இயலாது; குருவின் கீழ் வாழ்வதே அவற்றை அகற்றும்.\n\nகுருவின் சத்சங்கம் கவசம்; உலக ஈர்ப்புகளிலிருந்து பாதுகாப்பு.\n\nகுரு இன்றி பரிபூரணத்தை அடைந்த சிலர் விதிவிலக்குகள்; முன் பிறவிச் சாதனையின் விளைவு. அதனால் குருவின் முக்கியத்துவம் குறையாது.\n\n‘குருவை ஏற்காதே’ என்று சொல்வோர் போலி ஆசான்கள்; அவர்களைத் தவிர்.\n\nமகான்கள் அனைவருக்கும் குருக்கள் இருந்தனர்—கிருஷ்ணன், ராமன், இயேசு, தேவர்கள் அனைவருக்கும்.\n\nதொடக்கத்தில் தனிப்பட்ட குரு தேவை; மனத் தூய்மை, நெறி நிறைவு வந்த பின்பே கடவுளே குருவாகலாம்.\n\nகுரு தேர்வு\n\nமகாத்மாவின் அருகில் அமைதி, உந்துதல், சந்தேக நிவாரணம், பேராசை இன்றிய அன்பு இருந்தால்—அவரே உன் குரு. தேர்ந்த பின் முழுமையாகப் பின்பற்று; குருவின் வழியே கடவுள் வழிநடத்துவார்.\n\nமுழு பகுத்தறிவால் மட்டும் தேர்வு செய்யாதே. உன்னத குரு கிடைக்காவிட்டால், தூய்மையுடன் பாதையில் நடக்கும் சாதுவின் உபதேசங்களை ஏற்று.\n\nஅதுவும் கிடைக்காவிட்டால், ஞானிகள் எழுதிய நூல்களைப் பின்பற்று; அவர்களின் படத்தை வழிபட்டு நம்பிக்கையுடன் சாதனை செய். நேரம் வந்தால் மறைமுக உதவி கிடைக்கும்.\n\nஇறை உதவியின் மர்மம்\n\nஏகநாதர் ஆகாசவாணி கேட்டார்; துகாராம் கனவில் மந்திரம் பெற்றார்; நம்மாழ்வாரை மதுரகவியார் ஒளியால் கண்டார்—இவ்வாறு இறைவன் வழி காட்டுகிறான்.\n\nதகுதியுள்ள சீடருக்கு தகுதியான குரு குறையாது.\n\nஉலகம் உள்ளவரை குருகளும் வேதங்களும் இருப்பர்.\n\nசிக்ஷா–தீக்ஷா குருக்கள்\n\nஉலகக் கல்வி அளிப்பவர் சிக்ஷா குரு; மோக்ஷப் பாதை காட்டுபவர் தீக்ஷா குரு. சிக்ஷா குருக்கள் பலர்; தீக்ஷா குரு ஒருவரே.\n\nஒரே குருவை பின்பற்று\n\nபல குருக்கள் குழப்பம் தரும். அனைவரையும் கேள்; ஒருவரை மட்டும் பின்பற்று.\n\nகுரு பரம்பரை\n\nஆன்மீக ஞானம் குரு–சிஷ்ய பரம்பரையாகப் பரவுகிறது.\n\nதீக்ஷை—அர்த்தம்\n\nதீக்ஷை மந்திரம் மட்டும் அல்ல; உபதேசத்தின் ஆழம்.\n\nசக்தி-சஞ்சாரம்\n\nஆன்மீக சக்தி பார்வை, தொடு, சொல் மூலம் பரிமாறப்படுகிறது; பரம்பரையாக வழங்கப்படும் மறை அறிவு.\n\nஅருள் மற்றும் முயற்சி\n\nகுரு அதிசயமாக மோக்ஷம் தரமாட்டார். முயற்சி, தூய்மை, தியானம் அவசியம்.\n\nகுருவும் சாஸ்திரங்களும் வழி காட்டுவர்; அனுபவ ஞானம் உன் முயற்சியால் மட்டுமே.\n\nகுரு அருள் அனைத்தும் செய்யும்—அருள் பெற, குரு உபதேசத்தைப் பின்பற்று.'
      ),
      Article(
          heading: 'ராம ராஜ்யத்தின் வழி',
          body: 'அமர ஆன்மாக்களே!\n\nஉங்களை ஊக்குவித்து, உயர்த்தி, மாற்றும் தெய்வீகச் செய்தியை என் இதயத்தின் நிறைவுடன் அளிக்கிறேன். பலவீனத்திலிருந்து வலிமைக்கு, துயரத்திலிருந்து ஆனந்தத்திற்கு இட்டுச் செல்லும் இந்த ராமநவமி செய்தியை கவனமாகக் கேளுங்கள்.\n\nராமாயணம் உயிரைக் காக்கும் பாடங்களின் களஞ்சியம். இன்றைய உலகத்தை கலங்கடிக்கும் அதர்மத்தின் மூலத்தையும், அதை நீக்கும் வழியையும் அறிதல் அவசியம். ராமரின் வாழ்க்கையிலிருந்து இரண்டு பேரியல்கள்—சத்தியமும் தூய்மையும்—இன்றைய உலகின் அவசியம்.\n\nநவீனத்தின் பெயரில் நெறியும் ஒழுக்கமும் கொல்லப்பட்டுள்ளன. அரசியல் வஞ்சக விளையாட்டாக மாறியுள்ளது. வீடு, நாடு, உலகம்—எங்கும் அதே கதை.\n\nஆகவே சத்தியமும் தூய்மையும் உயர்ந்த பேரியல்களாக ஏற்றுக் கொள்ளுங்கள். ராமர் அவற்றின் உருவமே. தந்தையின் வாக்கை காக்க வனவாசம் சென்ற அவரது வாழ்க்கை சத்தியத்தின் உச்சம். ஏகபத்னி விரதம் தூய்மையின் உச்சம்.\n\n‘அக்னி தன் வெப்பத்தை இழக்கலாம்; நான் தந்தை வாக்கை இழக்க மாட்டேன்’—இந்த சத்தியத்தின் வலிமை அமரத்துவம் தரும்.\n\nசீதையின் நிலைத்தன்மை—சோதனைகளில் கூட சத்தியத்தின் தூய்மை.\n\nசிந்தனை, சொல், செயல்—மூன்றிலும் சத்தியம் எனும் திரிசூலத்தை ஏந்துங்கள். இது உண்மையான ராமபாணம்.\n\nஇந்த ராமநவமியில் என் பரிசு—சத்தியம், தூய்மை; ராமநாமம். இம்மூன்றும் உங்களை உச்சத்திற்கு உயர்த்தும்.\n\nஉன் உடல் தெய்வ ஆலயம்; இதயத்தில் சத்தியத்தை பிரதிஷ்டை செய்.\n\nஉண்மையான ராமராஜ்யம் உலகமெங்கும் அமைதியையும் நலனையும் தரும். சத்தியமே அதற்கான சக்தி.\n\nஇந்தக் கொள்கைகள் நடைமுறையில் வந்தால், மனிதகுலம் முழுவதும் ராமராஜ்யம் மலரும்.\n\nதிருவிழாக்கள் வாழ்வை ஊக்குவிக்கும். தினமும் ராமாயணத்தைப் படி; சத்தியம், தூய்மை உன் வாழ்வாகும்.'
      ),
      Article(
          heading: 'பகவத்கீதை',
          body: 'பகவத்கீதையின் தத்துவம் உபநிஷத்துகளின் தத்துவமே. ஆனால் அதை இல்லற வாழ்வின் மையத்திற்கு கொண்டு வந்து நடைமுறையாக்கியது கீதை. உபநிஷத்துகளின் ஆதேசமும் சன்தேசமும் தினசரி வாழ்வாக மாறியது கீதை.\n\nஉலகில் ஜீவாத்மா எதிர்கொள்ளும் இரட்டைமைகளின் மத்தியில், கடமை–இச்சை மோதல்களை கீதை எடுத்துரைக்கிறது. சரியான பார்வை இல்லாமையால் மனிதன் தவறான பாதை எடுப்பதை கீதை ஞான ஒளியால் நீக்குகிறது.\n\nகீதை உரையாடல் முறையில் போதிக்கும் கல்விச் செயல்முறை. ஆசான் சீடனை உயர்ந்த புரிதலுக்கு அழைத்துச் செல்கிறார்; சீடன் ஆசானின் பார்வையில் உலகைக் காணக் கற்றுக் கொள்கிறான்.'
      ),
      Article(
          heading: 'ஸ்ரீ ராமர்',
          body: 'ராவணனை அழிக்க பூமியில் அவதரித்த ஸ்ரீஹரியே ராமர். அழகு, வீரியம், ஞானம் நிறைந்தவர். தாமரை போன்ற கண்கள், பூர்ணசந்திரன் போன்ற முகம், சிங்கநடையுடன் மாட்சிமை.\n\nஅவர் தீமை அற்றவர், மக்களைக் காக்கும் கருணையாளர். கடுமை இல்லா சொற்கள்; மன்னிக்கும் பெருமை. சூரியன் போன்ற ஒளி, பூமி போன்ற பொறை, பிரகஸ்பதி போன்ற ஞானம்.\n\nசாஸ்திரங்களில் நிபுணர்; அரச கடமையில் உறுதியானவர். வல்லமை இருந்தும் அகம்பாவம் இல்லாதவர்.\n\nபொய் பேசாதவர்; சத்தியத்தின் காவலன். தந்தையின் வாக்கைக் காக்க அரசையும் இன்பங்களையும் துறந்தவர்.\n\nராமரின் ஆட்சி—நீதி, அமைதி, செழிப்பு. எவரும் துயருறாத காலம். அதனால் அது ‘ராமராஜ்யம்’ எனப் போற்றப்பட்டது.'
      )
    ],
);